diff --git a/app/components/home/HomeSearch.tsx b/app/components/home/HomeSearch.tsx
new file mode 100644
index 0000000..cb09c32
--- /dev/null
+++ b/app/components/home/HomeSearch.tsx
@@ -0,0 +1,203 @@
+"use client";
+
+import { useMemo } from "react";
+import { useLocale, useTranslations } from "next-intl";
+import { BookOpen, FileText, Search, SearchX, X } from "lucide-react";
+import { Link, useRouter } from "@/i18n/routing";
+import { SurahResult } from "@types";
+import { useReaderBasePath } from "@hooks/use-reader-base-path";
+import { useReaderNavigation } from "@contexts/ReaderNavigationContext";
+import { useVersePages } from "@hooks/use-verse-pages";
+import { useJuzStarts } from "@hooks/use-juz-starts";
+import {
+  jumpRows,
+  NAV_SEARCH,
+  pageOfVerseKey,
+  parseNavQuery,
+  rangeHint,
+  surahMatchesQuery,
+} from "@utils/nav-search";
+import { toLocaleNumeral } from "@utils/i18n";
+import { SurahList } from "@components/SurahList";
+import { cn } from "@/lib/utils";
+
+type Props = {
+  surahs: SurahResult[];
+  query: string;
+  onQueryChange: (value: string) => void;
+};
+
+// Navigation search for the home page: filters the surah grid by name/number
+// and offers Juz/Page jump rows. Verse-text search stays in the global nav
+// SearchBar — this surface never queries an API.
+export const HomeSearch = ({ surahs, query, onQueryChange }: Props) => {
+  const t = useTranslations("home");
+  const locale = useLocale();
+  const router = useRouter();
+  const basePath = useReaderBasePath();
+  const { jumpTo } = useReaderNavigation();
+
+  // Lazy: the ~73KB verse-pages map is only fetched once a juz intent
+  // appears; page jumps need no data at all.
+  const parsed = useMemo(() => parseNavQuery(query), [query]);
+  const needsJuzData =
+    parsed.number !== null &&
+    parsed.number >= 1 &&
+    parsed.number <= NAV_SEARCH.juzCount &&
+    (parsed.prefix === "juz" || parsed.prefix === null);
+  const { data: juzStarts } = useJuzStarts(needsJuzData);
+  const { data: versePages } = useVersePages(needsJuzData);
+
+  const rows = useMemo(() => jumpRows(parsed), [parsed]);
+  const filtered = useMemo(
+    () => (parsed.text ? surahs.filter((s) => surahMatchesQuery(s, parsed)) : surahs),
+    [surahs, parsed],
+  );
+  const hint = rangeHint(parsed);
+  const isFiltering = parsed.text.length > 0;
+
+  // null = not resolvable yet (juz data still loading) — rows render without
+  // a page and Enter skips them rather than navigating to a wrong target.
+  const rowPage = (kind: "juz" | "page", n: number): number | null => {
+    if (kind === "page") return n;
+    const start = juzStarts?.find((j) => j.juz === n);
+    if (!start) return null;
+    return pageOfVerseKey(versePages, start.verse_key, start.defaultPage);
+  };
+
+  const navigateToPage = (page: number) => router.push(`${basePath}/${page}`);
+
+  // Enter activates the most specific target: first jump row, else first card.
+  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
+    if (e.key === "Escape") {
+      onQueryChange("");
+      return;
+    }
+    if (e.key !== "Enter") return;
+    e.preventDefault();
+    const firstRow = rows[0];
+    if (firstRow) {
+      const page = rowPage(firstRow.kind, firstRow.n);
+      if (page !== null) navigateToPage(page);
+      return;
+    }
+    const firstCard = filtered[0];
+    if (firstCard) navigateToPage(Number(firstCard.pages.split("-")[0]));
+  };
+
+  const showGrid = !isFiltering || filtered.length > 0 || rows.length === 0;
+
+  return (
+    <section aria-label={t("searchLabel")} className="relative">
+      {/* Static control bar — scrolls with the page (sticky rejected in live
+          review: cards showed through around the bar's edges). */}
+      <div className="py-1">
+        <div className="relative flex items-center">
+          <Search
+            className="size-4 text-muted-foreground absolute start-3 pointer-events-none"
+            strokeWidth={1.8}
+            aria-hidden="true"
+          />
+          <input
+            type="text"
+            value={query}
+            onChange={(e) => onQueryChange(e.target.value)}
+            onKeyDown={handleKeyDown}
+            placeholder={t("searchPlaceholder")}
+            aria-label={t("searchPlaceholder")}
+            dir="auto"
+            className="fq-focus-ring w-full h-10 rounded-xl border border-border bg-card ps-9 pe-10 text-sm text-foreground placeholder:text-muted-foreground font-tajawal transition-colors duration-150 hover:border-primary/40 focus:border-primary/60 outline-none"
+          />
+          {isFiltering && (
+            <button
+              type="button"
+              onClick={() => onQueryChange("")}
+              aria-label={t("searchClear")}
+              className="absolute end-2 size-7 grid place-items-center rounded-md text-muted-foreground hover:text-foreground hover:bg-[hsl(var(--well)/var(--well-alpha))] transition-colors duration-150 fq-focus-ring"
+            >
+              <X className="size-4" strokeWidth={1.8} />
+            </button>
+          )}
+        </div>
+
+        {/* Live result count */}
+        {isFiltering && filtered.length > 0 && (
+          <p className="mt-1.5 text-xs text-muted-foreground" role="status">
+            {t("resultsCount", { count: toLocaleNumeral(filtered.length, locale) })}
+          </p>
+        )}
+
+        {/* Out-of-range hint ("page 999" → Pages 1–604) */}
+        {hint && (
+          <p className="mt-1.5 text-xs text-muted-foreground" role="status">
+            {hint === "juz"
+              ? t("juzRangeHint", {
+                  min: toLocaleNumeral(1, locale),
+                  max: toLocaleNumeral(NAV_SEARCH.juzCount, locale),
+                })
+              : t("pageRangeHint", {
+                  min: toLocaleNumeral(1, locale),
+                  max: toLocaleNumeral(NAV_SEARCH.lastPage, locale),
+                })}
+          </p>
+        )}
+
+        {/* Jump rows — suggestions only, never auto-committed */}
+        {rows.length > 0 && (
+          <ul className="mt-2 flex flex-col gap-1.5">
+            {rows.map((row) => {
+              const isJuz = row.kind === "juz";
+              const Icon = isJuz ? BookOpen : FileText;
+              const page = rowPage(row.kind, row.n);
+              return (
+                <li key={row.kind}>
+                  <Link
+                    href={`${basePath}/${page ?? 1}`}
+                    locale={locale}
+                    aria-disabled={page === null}
+                    onClick={(e) => {
+                      if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
+                      // Juz data still loading — inert rather than wrong.
+                      if (page === null) {
+                        e.preventDefault();
+                        return;
+                      }
+                      if (!jumpTo) return;
+                      e.preventDefault();
+                      jumpTo(page);
+                    }}
+                    className="fq-focus-ring flex items-center gap-2.5 px-3 py-2 rounded-xl border border-border bg-card hover:border-primary/50 transition-colors duration-150 text-sm text-foreground"
+                  >
+                    <Icon className="size-4 shrink-0 text-primary" strokeWidth={1.7} aria-hidden="true" />
+                    {isJuz
+                      ? page !== null
+                        ? t("juzRow", {
+                            n: toLocaleNumeral(row.n, locale),
+                            page: toLocaleNumeral(page, locale),
+                          })
+                        : t("juzRowShort", { n: toLocaleNumeral(row.n, locale) })
+                      : t("pageRow", { n: toLocaleNumeral(row.n, locale) })}
+                  </Link>
+                </li>
+              );
+            })}
+          </ul>
+        )}
+      </div>
+
+      {!showGrid ? null : filtered.length > 0 ? (
+        <SurahList surahs={filtered} className="mt-4" />
+      ) : (
+        isFiltering && (
+          <div className="flex flex-col items-center gap-3 px-6 py-16 text-center">
+            <span className="fq-well grid size-12 place-items-center rounded-2xl text-muted-foreground">
+              <SearchX className="size-6" strokeWidth={1.6} />
+            </span>
+            <p className="text-sm font-medium text-foreground">{t("noMatches")}</p>
+            <p className={cn("text-xs text-muted-foreground max-w-xs")}>{t("verseSearchHint")}</p>
+          </div>
+        )
+      )}
+    </section>
+  );
+};
diff --git a/app/components/home/HomeSearchSection.tsx b/app/components/home/HomeSearchSection.tsx
new file mode 100644
index 0000000..416f847
--- /dev/null
+++ b/app/components/home/HomeSearchSection.tsx
@@ -0,0 +1,28 @@
+"use client";
+
+import { useState } from "react";
+import { SurahResult } from "@types";
+import { HomeContinueReadingCard } from "@components/home/HomeContinueReadingCard";
+import { HomeRecommendedSurahs } from "@components/home/HomeRecommendedSurahs";
+import { HomeSearch } from "@components/home/HomeSearch";
+
+type Props = {
+  surahs: SurahResult[];
+};
+
+// One client boundary around the interactive band of the home page so the
+// continue-reading card, recommended chips and search field react to a single
+// query string. Idle state renders everything (matching SSR); an active query
+// hides the extras and lets results own the page.
+export const HomeSearchSection = ({ surahs }: Props) => {
+  const [query, setQuery] = useState("");
+  const isFiltering = query.trim().length > 0;
+
+  return (
+    <>
+      {!isFiltering && <HomeContinueReadingCard surahs={surahs} />}
+      {!isFiltering && <HomeRecommendedSurahs surahs={surahs} />}
+      <HomeSearch surahs={surahs} query={query} onQueryChange={setQuery} />
+    </>
+  );
+};
diff --git a/app/components/nav/AyahPicker.tsx b/app/components/nav/AyahPicker.tsx
new file mode 100644
index 0000000..c7c0f1b
--- /dev/null
+++ b/app/components/nav/AyahPicker.tsx
@@ -0,0 +1,292 @@
+"use client";
+
+import { useMemo, useState } from "react";
+import { useLocale, useTranslations as useNextIntlTranslations } from "next-intl";
+import { SurahResult } from "@types";
+import { toLocaleNumeral } from "@/app/utils/i18n";
+import { useVersePages } from "@hooks/use-verse-pages";
+import { useSidebar } from "@/app/contexts/SidebarContext";
+import { useReaderNavigation } from "@/app/contexts/ReaderNavigationContext";
+import {
+  NAV_SEARCH,
+  parseAyahNumber,
+  parseNavQuery,
+  surahMatchesQuery,
+} from "@utils/nav-search";
+import { ChevronDown } from "lucide-react";
+import { cn } from "@/lib/utils";
+
+type Props = {
+  // The surah the reader is currently in (Sidebar's activeSurah — pin-aware);
+  // the picker's DEFAULT target. All 114 are passed so the inline list can
+  // retarget (#433).
+  surah: SurahResult;
+  surahs: SurahResult[];
+  currentPage: number;
+};
+
+// Third sidebar tab (#433): pick a surah (defaults to current), then an ayah by
+// number or chip, or type any page number 1–604. The surah list swaps inline
+// into the tab body (Option A) rather than a popover — no portals, no
+// focus-trap container plumbing inside the Sheet. Landing reuses jumpTo for
+// the instant pager swap; the highlight is then stamped onto the URL with
+// history.replaceState AFTER jumpTo (jumpTo writes a bare path, so it must go
+// first) — Next ≥14.1 syncs replaceState searchParams into QuranWord's
+// useSearchParams, coloring the verse without new prop plumbing. The next page
+// turn replaces the URL bare again, clearing the highlight naturally.
+const AyahPicker = ({ surah, surahs, currentPage }: Props) => {
+  const tSidebar = useNextIntlTranslations("sidebar");
+  const locale = useLocale();
+  const { setOpen } = useSidebar();
+  const { jumpTo } = useReaderNavigation();
+  const { data: versePages } = useVersePages();
+  // verse_key → page map is SW-precached; until it lands there is no honest
+  // page to promise any ayah, so chips stay inert instead of guessing. The
+  // page field is unaffected — a page number needs no map to be an address.
+  const ready = !!versePages;
+
+  // Radix unmounts inactive TabsContent, so this useState initializer re-runs
+  // on every tab/sheet open — the target always starts at the CURRENT surah,
+  // and only a deliberate list pick moves it (stays put across page turns
+  // while the sheet stays open).
+  const [target, setTarget] = useState(surah);
+  const [picking, setPicking] = useState(false);
+  const [listQuery, setListQuery] = useState("");
+
+  // Shared grammar with tab 1's filter: hamza-folded names AND bare surah
+  // numbers ("18" finds الكهف).
+  const parsedList = useMemo(() => parseNavQuery(listQuery), [listQuery]);
+  const filteredList = useMemo(
+    () =>
+      parsedList.text
+        ? surahs.filter((s) => surahMatchesQuery(s, parsedList))
+        : surahs,
+    [surahs, parsedList],
+  );
+
+  const [raw, setRaw] = useState("");
+  const n = useMemo(() => parseAyahNumber(raw), [raw]);
+  const outOfRange = n !== null && (n < 1 || n > target.verses_count);
+
+  const [pageRaw, setPageRaw] = useState("");
+  const pageN = useMemo(() => parseAyahNumber(pageRaw), [pageRaw]);
+  const pageOutOfRange =
+    pageN !== null && (pageN < 1 || pageN > NAV_SEARCH.lastPage);
+
+  const pageOfAyah = (ayah: number) => versePages?.[`${target.id}:${ayah}`];
+
+  const jumpToAyah = (ayah: number) => {
+    if (!ready || !jumpTo) return;
+    if (ayah < 1 || ayah > target.verses_count) return;
+    const page = pageOfAyah(ayah);
+    if (!page) return;
+    jumpTo(page);
+    const url = new URL(window.location.href);
+    url.searchParams.set("highlight", `${target.id}:${ayah}`);
+    url.searchParams.set("highlight-type", "search");
+    window.history.replaceState(null, "", url.toString());
+    setOpen(false);
+  };
+
+  const jumpToPage = () => {
+    if (!jumpTo) return;
+    if (pageN === null || pageOutOfRange) return;
+    jumpTo(pageN);
+    setOpen(false);
+  };
+
+  const pickTarget = (s: SurahResult) => {
+    setTarget(s);
+    setPicking(false);
+    setListQuery("");
+    setRaw("");
+  };
+
+  // Shared clear-first Escape contract with the #362 filter field: a non-empty
+  // input clears itself before letting Radix close the sheet.
+  const makeKeyDown =
+    (value: string, clear: () => void, submit: () => void) =>
+    (e: React.KeyboardEvent<HTMLInputElement>) => {
+      if (e.key === "Escape") {
+        if (value.trim()) {
+          e.stopPropagation();
+          clear();
+        }
+        return;
+      }
+      if (e.key !== "Enter") return;
+      e.preventDefault();
+      submit();
+    };
+
+  const countText = tSidebar("ayahCount", {
+    count: target.verses_count,
+    n: toLocaleNumeral(target.verses_count, locale),
+  });
+
+  return (
+    <div className="px-4 py-3">
+      {/* Target selector — tapping swaps the body to the searchable surah list */}
+      <button
+        type="button"
+        onClick={() => setPicking((p) => !p)}
+        aria-expanded={picking}
+        className="fq-focus-ring w-full flex items-center justify-between gap-2 rounded-xl px-1 py-1 text-start hover:bg-[hsl(var(--well)/var(--well-alpha))] transition-colors duration-150"
+      >
+        <span className="flex items-center gap-2 min-w-0">
+          <span className="text-sm font-medium truncate" dir="auto">
+            {locale === "ar" ? target.name_arabic : target.name_simple}
+          </span>
+        </span>
+        <span className="flex items-center gap-1.5 shrink-0 text-muted-foreground">
+          <span className="text-xs whitespace-nowrap">{countText}</span>
+          <ChevronDown
+            className={cn("size-4 transition-transform duration-150", picking && "rotate-180")}
+            strokeWidth={1.8}
+          />
+        </span>
+      </button>
+
+      {picking ? (
+        <div className="mt-2.5">
+          <input
+            type="text"
+            value={listQuery}
+            onChange={(e) => setListQuery(e.target.value)}
+            onKeyDown={makeKeyDown(listQuery, () => setListQuery(""), () => {
+              if (filteredList.length > 0) pickTarget(filteredList[0]);
+            })}
+            placeholder={tSidebar("ayahPickSurah")}
+            aria-label={tSidebar("ayahPickSurah")}
+            dir={locale === "ar" ? "rtl" : "ltr" }
+            className={cn(
+              "fq-focus-ring w-full h-10 rounded-xl border bg-card px-4 text-sm text-foreground",
+              "placeholder:text-muted-foreground transition-colors duration-150 outline-none",
+              "border-border hover:border-primary/40 focus:border-primary/60",
+            )}
+          />
+          {filteredList.length === 0 ? (
+            <p className="mt-3 text-sm text-muted-foreground text-center" role="status">
+              {tSidebar("filterNoMatches")}
+            </p>
+          )           : (
