+    expect(parseNavQuery("hizb 12")).toEqual({ text: "hizb 12", number: 12, prefix: "hizb" });
+    expect(parseNavQuery("حزب ١٢")).toEqual({ text: "حزب 12", number: 12, prefix: "hizb" });
